// @vitest-environment node
import { Zip, ZipPassThrough, zipSync, type Zippable } from 'fflate'
import { describe, expect, it } from 'vitest'
import { MAX_ENTRY_BYTES, readZip, type ZipItem } from './unzip'
import { noise, noiseWithSignatures, streamedZip, zip64Zip, zipFile as asFile } from './zipFixture'

// T-0032 (D-0035): the unzip step, on zips built here from generated bytes (no real photos).

async function collect(zip: File, options?: Parameters<typeof readZip>[1]) {
  const items: ZipItem[] = []
  for await (const item of readZip(zip, options)) items.push(item)
  return items
}

/** Where the first central directory entry is, from the end-of-directory record. */
const firstCentral = (zip: Uint8Array) => new DataView(zip.buffer, zip.byteOffset, zip.byteLength).getUint32(zip.length - 22 + 16, true)

const bytesOf = async (file: File) => new Uint8Array(await file.arrayBuffer())

describe('readZip', () => {
  it('yields only the images, in zip order, with their bytes unchanged', async () => {
    const a = noise(3000, 1)
    const b = noise(5000, 2)
    const zip = zipSync({
      'a.jpg': a,
      'sub/b.JPEG': b,
      'notes.txt': new TextEncoder().encode('lijm kopen'),
      '__MACOSX/._a.jpg': noise(100, 3),
      '.DS_Store': noise(100, 4),
      'inner.zip': zipSync({ 'c.jpg': noise(100, 5) }),
    } satisfies Zippable)

    const items = await collect(asFile(zip))
    expect(items.map((i) => i.kind)).toEqual(['image', 'image'])
    const [first, second] = items as Array<Extract<ZipItem, { kind: 'image' }>>
    expect(first!.path).toBe('a.jpg')
    expect(second!.path).toBe('sub/b.JPEG')
    expect(await bytesOf(first!.file)).toEqual(a)
    expect(await bytesOf(second!.file)).toEqual(b)
    // The File carries no folder in its name, the image type of its extension and the zip's date.
    expect(second!.file.name).toBe('b.JPEG')
    expect(second!.file.type).toBe('image/jpeg')
    expect(second!.file.lastModified).toBe(Date.UTC(2026, 10, 1, 12))
  })

  it('skips folders, dotfiles and other files at any depth, and takes every image type of D-0035', async () => {
    const zip = zipSync({
      'Tuin/': new Uint8Array(0),
      'Tuin/dag 2/IMG_7.png': noise(10, 1),
      'Tuin/.thumbnails/t.jpg': noise(10, 2),
      'Tuin/._IMG_7.png': noise(10, 3),
      'x.webp': noise(10, 4),
      'x.HEIC': noise(10, 5),
      'x.heif': noise(10, 6),
      'x.avif': noise(10, 7),
      'x.gif': noise(10, 8),
      'x.bmp': noise(10, 9),
      'Thumbs.db': noise(10, 10),
      'film.mov': noise(10, 11),
    })
    const items = (await collect(asFile(zip))) as Array<Extract<ZipItem, { kind: 'image' }>>
    expect(items.map((i) => [i.path, i.file.type])).toEqual([
      ['Tuin/dag 2/IMG_7.png', 'image/png'],
      ['x.webp', 'image/webp'],
      ['x.HEIC', 'image/heic'],
      ['x.heif', 'image/heif'],
      ['x.avif', 'image/avif'],
      ['x.gif', 'image/gif'],
    ])
  })

  it('lists an image over the limit with a reason and still yields the images after it', async () => {
    const zip = zipSync({ 'a.jpg': noise(500, 1), 'groot.jpg': noise(2000, 2), 'c.jpg': noise(500, 3) })
    const items = await collect(asFile(zip), { limit: 1000 })
    expect(items.map((i) => (i.kind === 'image' ? ['image', i.path] : [i.kind, 'path' in i ? i.path : '', i.reason]))).toEqual([
      ['image', 'a.jpg'],
      ['entry-failure', 'groot.jpg', 'is groter dan 40 MB'],
      ['image', 'c.jpg'],
    ])
  })

  it('stops unpacking an image once it passes the limit, also when the zip gives no size up front', async () => {
    // Zeros compress about 1000 to 1: the size is only found by unpacking.
    const zip = streamedZip({ 'a.jpg': noise(500, 1), 'nul.jpg': new Uint8Array(400_000), 'c.jpg': noise(500, 3) })
    expect(zip.length).toBeLessThan(10_000)
    const items = await collect(asFile(zip), { limit: 100_000 })
    expect(items.map((i) => [i.kind, 'path' in i ? i.path : ''])).toEqual([
      ['image', 'a.jpg'],
      ['entry-failure', 'nul.jpg'],
      ['image', 'c.jpg'],
    ])
    expect(await bytesOf((items[2] as Extract<ZipItem, { kind: 'image' }>).file)).toEqual(noise(500, 3))
  })

  it('uses 40 MB as the limit by default', () => {
    expect(MAX_ENTRY_BYTES).toBe(40 * 1024 * 1024)
  })

  it('gives one failure for bytes that are not a zip', async () => {
    expect(await collect(asFile(new TextEncoder().encode('dit is geen zip'), 'kapot.zip'))).toEqual([
      { kind: 'zip-failure', reason: 'kon niet worden uitgepakt' },
    ])
    expect(await collect(asFile(new Uint8Array(0), 'leeg.zip'))).toEqual([{ kind: 'zip-failure', reason: 'kon niet worden uitgepakt' }])
  })

  it('says a zip without images has no photos', async () => {
    const onlyJunk = zipSync({ 'notes.txt': noise(10), 'inner.zip': zipSync({ 'a.jpg': noise(10) }) })
    expect(await collect(asFile(onlyJunk))).toEqual([{ kind: 'zip-failure', reason: "bevat geen foto's" }])
    expect(await collect(asFile(zipSync({})))).toEqual([{ kind: 'zip-failure', reason: "bevat geen foto's" }])
  })

  it('keeps the images before a break and says the zip could not be read completely', async () => {
    const zip = zipSync({ 'a.jpg': noise(3000, 1), 'b.jpg': noise(3000, 2) }, { level: 0 })
    const cut = zip.subarray(0, 3000 + 30 + 5 + 1000) // into b.jpg's data
    const items = await collect(asFile(cut))
    expect(items.map((i) => i.kind)).toEqual(['image', 'zip-failure'])
    expect(items[1]).toEqual({ kind: 'zip-failure', reason: 'kon niet helemaal worden uitgepakt' })

    // Cut inside the first image: nothing came out.
    expect(await collect(asFile(zip.subarray(0, 1000)))).toEqual([{ kind: 'zip-failure', reason: 'kon niet worden uitgepakt' }])
  })

  it('lists an entry it cannot unpack (an encrypted one) and goes on with the next', async () => {
    const zip = zipSync({ 'geheim.jpg': noise(2000, 1), 'b.jpg': noise(500, 2) })
    // AES encryption marks an entry with compression method 99, in its local and central headers.
    const view = new DataView(zip.buffer, zip.byteOffset, zip.byteLength)
    view.setUint16(8, 99, true)
    view.setUint16(firstCentral(zip) + 10, 99, true)
    const items = await collect(asFile(zip))
    expect(items.map((i) => [i.kind, 'path' in i ? i.path : '', 'reason' in i ? i.reason : ''])).toEqual([
      ['entry-failure', 'geheim.jpg', 'kon niet worden uitgepakt'],
      ['image', 'b.jpg', ''],
    ])
  })

  it('lists a damaged entry and goes on with the next', async () => {
    const good = noise(500, 2)
    const zip = zipSync({ 'kapot.jpg': new Uint8Array(5000), 'b.jpg': good })
    // Garbage instead of the first entry's deflate data (after its 30-byte header and name).
    zip.fill(0xff, 30 + 'kapot.jpg'.length, 30 + 'kapot.jpg'.length + 8)
    const items = await collect(asFile(zip))
    expect(items[0]).toEqual({ kind: 'entry-failure', path: 'kapot.jpg', reason: 'kon niet worden uitgepakt' })
    expect(items.some((i) => i.kind === 'image' && i.path === 'b.jpg')).toBe(true)
  })

  it('reads stored and streamed zips alike, and reports progress up to the whole zip', async () => {
    const chunks: Uint8Array[] = []
    const zip = new Zip((err, chunk) => {
      if (!err) chunks.push(chunk)
    })
    const stored = new ZipPassThrough('a.jpg')
    zip.add(stored)
    stored.push(noise(70_000, 1), true)
    zip.end()
    const bytes = new Uint8Array(chunks.reduce((n, c) => n + c.length, 0))
    let at = 0
    for (const c of chunks) bytes.set(c, (at += c.length) - c.length)

    const progress: number[] = []
    const items = await collect(asFile(bytes), { onProgress: (read, total) => progress.push(Math.floor((read * 100) / total)) })
    expect(items.map((i) => i.kind)).toEqual(['image'])
    expect(await bytesOf((items[0] as Extract<ZipItem, { kind: 'image' }>).file)).toEqual(noise(70_000, 1))
    expect(progress.at(-1)).toBe(100)
  })

  it('reads the next piece of the zip only when asked for the next image', async () => {
    const zip = zipSync({ 'a.jpg': noise(300_000, 1), 'b.jpg': noise(300_000, 2) }, { level: 0 })
    let read = 0
    const reader = readZip(asFile(zip), { onProgress: (r) => (read = r) })
    const first = await reader.next()
    expect(first.value).toMatchObject({ kind: 'image', path: 'a.jpg' })
    const readAtFirst = read
    // The consumer is busy with a.jpg: nothing more has been read meanwhile.
    await new Promise((resolve) => setTimeout(resolve, 20))
    expect(read).toBe(readAtFirst)
    expect(read).toBeLessThan(zip.length)
    expect((await reader.next()).value).toMatchObject({ kind: 'image', path: 'b.jpg' })
    expect((await reader.next()).done).toBe(true)
  })
})

// Sent back by the tester: a zip whose entries have data descriptors (sizes after the data)
// must not be cut at bytes in a photo that look like a zip signature.
describe('readZip on zips with data descriptors', () => {
  const images = (items: ZipItem[]) =>
    items.map((i) => (i.kind === 'image' ? `image ${i.path}` : `${i.kind} ${'path' in i ? i.path + ' ' : ''}${i.reason}`))

  for (const stored of [false, true]) {
    const how = stored ? 'stored' : 'deflated'

    it(`gives every ${how} image byte for byte, even when its data holds zip signatures`, async () => {
      const a = noiseWithSignatures(200_000, 1)
      const b = noiseWithSignatures(50_000, 2)
      const zip = streamedZip({ 'a.jpg': a, 'sub/b.jpg': b, 'c.jpg': noise(1000, 3) }, { stored })
      const items = await collect(asFile(zip))
      expect(images(items)).toEqual(['image a.jpg', 'image sub/b.jpg', 'image c.jpg'])
      const files = items as Array<Extract<ZipItem, { kind: 'image' }>>
      expect(await bytesOf(files[0]!.file)).toEqual(a)
      expect(await bytesOf(files[1]!.file)).toEqual(b)
      expect(await bytesOf(files[2]!.file)).toEqual(noise(1000, 3))
    })

    it(`never opens a ${how} zip inside the zip`, async () => {
      const inner = zipSync({ 'secret.jpg': noise(5000, 4) }, { level: 0 })
      const zip = streamedZip({ 'inner.zip': inner, 'ok.jpg': noise(1000, 5) }, { stored })
      expect(images(await collect(asFile(zip)))).toEqual(['image ok.jpg'])
    })
  }

  it('lists an image whose bytes do not match its CRC-32, and goes on', async () => {
    const zip = zipSync({ 'a.jpg': noise(3000, 1), 'b.jpg': noise(500, 2) }, { level: 0 })
    zip[30 + 'a.jpg'.length + 1000]! ^= 0xff // one byte of a.jpg's stored data
    expect(images(await collect(asFile(zip)))).toEqual(['entry-failure a.jpg kon niet worden uitgepakt', 'image b.jpg'])
  })

  it('stops unpacking at the limit when the directory gives a size that is too small', async () => {
    const zip = zipSync({ 'nul.jpg': new Uint8Array(400_000), 'c.jpg': noise(500, 3) })
    // Claim a tiny unpacked size in both headers: the reader must still stop at the limit.
    const view = new DataView(zip.buffer, zip.byteOffset, zip.byteLength)
    view.setUint32(22, 10, true)
    view.setUint32(firstCentral(zip) + 24, 10, true)
    expect(images(await collect(asFile(zip), { limit: 100_000 }))).toEqual([
      'entry-failure nul.jpg is groter dan 40 MB',
      'image c.jpg',
    ])
  })

  it('lists an entry flagged as password-protected, and goes on', async () => {
    const zip = zipSync({ 'geheim.jpg': noise(2000, 1), 'b.jpg': noise(500, 2) }, { level: 0 })
    const view = new DataView(zip.buffer, zip.byteOffset, zip.byteLength)
    view.setUint16(6, 1, true)
    view.setUint16(firstCentral(zip) + 8, 1, true)
    expect(images(await collect(asFile(zip)))).toEqual(['entry-failure geheim.jpg kon niet worden uitgepakt', 'image b.jpg'])
  })

  it('does not guess where an entry ends in a cut-short zip with data descriptors', async () => {
    const zip = streamedZip({ 'a.jpg': noiseWithSignatures(50_000, 1), 'b.jpg': noise(500, 2) }, { stored: true })
    expect(images(await collect(asFile(zip.subarray(0, zip.length - 30))))).toEqual(['zip-failure kon niet worden uitgepakt'])
  })

  it('reads a ZIP64 zip', async () => {
    const a = noiseWithSignatures(20_000, 1)
    const items = await collect(asFile(zip64Zip({ 'a.jpg': a, 'readme.txt': noise(10, 2), 'b.jpg': noise(100, 3) })))
    expect(images(items)).toEqual(['image a.jpg', 'image b.jpg'])
    expect(await bytesOf((items[0] as Extract<ZipItem, { kind: 'image' }>).file)).toEqual(a)
  })

  it('does not read entries it skips', async () => {
    const zip = zipSync({ 'film.mov': noise(2_000_000, 1), 'a.jpg': noise(100, 2) }, { level: 0 })
    const file = asFile(zip)
    let sliced = 0
    const spy = new Proxy(file, {
      get(target, prop) {
        if (prop === 'slice')
          return (start?: number, end?: number) => {
            sliced += (end ?? target.size) - (start ?? 0)
            return target.slice(start, end)
          }
        if (prop === 'stream')
          return () => {
            sliced += target.size
            return target.stream()
          }
        const value = Reflect.get(target, prop, target)
        return typeof value === 'function' ? value.bind(target) : value
      },
    })
    expect(images(await collect(spy as File))).toEqual(['image a.jpg'])
    expect(sliced).toBeLessThan(200_000)
  })
})
